    def propose_action(self, body: ActionProposeIn | dict[str, Any]) -> ActionOut:
        """POST /v1/fleet/actions -- Propose Action

        Propose an enforcement action. ALWAYS created dry_run=TRUE and
        status='proposed'. A requester can never self-grant a real apply.
        """
        return self._request('POST', '/v1/fleet/actions', body=body)

    def approve_action(self, action_id: str, body: ApproveIn | dict[str, Any]) -> ActionOut:
        """POST /v1/fleet/actions/{action_id}/approve -- Approve Action

        Admin-only. proposed -> approved. Sets approved_by + decided_at.
        Four-eyes: the approver must differ from the requester. A REAL host change
        requires ``apply_for_real=true`` (which flips dry_run to false) -- the
        single, conscious human act that satisfies safety rails #2 and #3.
        """
        return self._request('POST', '/v1/fleet/actions/{action_id}/approve', path_params={'action_id': action_id}, body=body)

    def deny_action(self, action_id: str, body: DenyIn | dict[str, Any]) -> ActionOut:
        """POST /v1/fleet/actions/{action_id}/deny -- Deny Action

        Admin-only. proposed -> denied.
        """
        return self._request('POST', '/v1/fleet/actions/{action_id}/deny', path_params={'action_id': action_id}, body=body)

    def post_result(self, action_id: str, body: ResultIn | dict[str, Any]) -> ActionOut:
        """POST /v1/fleet/actions/{action_id}/result -- Post Result

        Agent reports the outcome of a real apply. Guards enforce rails #2 + #3:
        an action may only be reported ``applied`` when it is ``approved`` AND
        ``dry_run = false``. A dry-run can never mutate, so it can never be
        ``applied`` here.
        """
        return self._request('POST', '/v1/fleet/actions/{action_id}/result', path_params={'action_id': action_id}, body=body)

    def revert_action(self, action_id: str, body: RevertIn | dict[str, Any]) -> ActionOut:
        """POST /v1/fleet/actions/{action_id}/revert -- Revert Action

        Mint a first-class, pre-approved REVERT action for an applied block.
        Reverting is de-escalation (removing a block), so it is auto-approved but
        still audited; the agent executes it and reports a result, at which point
        the original action transitions to 'reverted'.
        """
        return self._request('POST', '/v1/fleet/actions/{action_id}/revert', path_params={'action_id': action_id}, body=body)

